INSERT INTO curiosita (id, titolo, tag, statistica, descrizione, fonte, anno, hashtag) VALUES (1, 'I 115 Gol Eterni di Diego Armando Maradona', 'RECORD ALL-TIME', '115 gol in 259 gare ufficiali (1984–1991)', 'Diego Armando Maradona ha guidato la classifica marcatori all-time del Napoli per oltre 26 anni (dal 1991 al 2017). Ha segnato 81 reti in Serie A, 29 in Coppa Italia e 5 nelle competizioni europee, decidendo scudetti e coppe con punizioni e giocate rimaste leggenda.', 'Almanacco Illustrato del Calcio Panini / Archivio Storico SSC Napoli', 1991, '#Maradona #D10S #SSCNapoli #DataNapoli');
INSERT INTO curiosita (id, titolo, tag, statistica, descrizione, fonte, anno, hashtag) VALUES (2, 'Il Record di Solidità del 1° Scudetto (1986-87)', 'DOPPIETTA STORICA', '42 punti su 30 gare · Miglior difesa del torneo con soli 19 gol subiti', 'Il Napoli di Ottavio Bianchi chiuse la Serie A 1986-87 con sole 3 sconfitte e vinse tutte le 13 partite disputate in Coppa Italia. Un ''Double'' campionato-coppa riuscito solo a tre club nella storia del calcio italiano.', 'Report Ufficiale Lega Serie A (1986-87)', 1987, '#Scudetto1987 #NapoliCampione #Double #Statistiche');
INSERT INTO curiosita (id, titolo, tag, statistica, descrizione, fonte, anno, hashtag) VALUES (3, 'Il Dominio Assoluto del 3° Scudetto (2022-23)', 'TRIONFO SPALLETTI', '90 punti · 77 gol fatti · +16 sulla seconda · Osimhen capocannoniere (26)', 'La squadra di Luciano Spalletti ha conquistato il titolo tricolore con 5 turni d''anticipo (4 maggio 2023 alla Dacia Arena di Udine), stabilendo il record di vittorie consecutive e la miglior differenza reti del torneo (+49).', 'Lega Serie A TIM / Opta Sports', 2023, '#Napul3 #Spalletti #Osimhen #Kvaratskhelia');
INSERT INTO curiosita (id, titolo, tag, statistica, descrizione, fonte, anno, hashtag) VALUES (4, 'L''Unico Club a Vincere la Coppa Italia in Serie B (1961-62)', 'PRIMATO NAZIONALE', 'Napoli-SPAL 2-1 all''Olimpico di Roma (21 giugno 1962)', 'Il Napoli guidato da Bruno Pesaola compì un''impresa mai più ripetuta in oltre un secolo di calcio: sollevare il trofeo della Coppa Italia militando nel campionato di Serie B e conquistando contestualmente la promozione in A.', 'FIGC / Archivio Storico Coppa Italia', 1962, '#Pesaola #CoppaItalia #StoriaAzzurra #Record');
INSERT INTO curiosita (id, titolo, tag, statistica, descrizione, fonte, anno, hashtag) VALUES (5, 'L''Acquisto Record Mondiale di Hasse Jeppson (1952)', 'CALCIOMERCATO EPICO', '105 milioni di lire versati all''Atalanta dal comandante Achille Lauro', 'Nel 1952 il presidente Achille Lauro polverizzò il primato mondiale di spesa calcistica acquistando il bomber svedese Hasse Jeppson. L''entità del costo spinse i tifosi partenopei a ribattezzarlo popolarmente ''o Banco ''e Napule''.', 'La Gazzetta dello Sport / Corriere dello Sport (1952)', 1952, '#Jeppson #AchilleLauro #BancoENapule #Calciomercato');
